INSERT IGNORE INTO `country` (`countryID`, `name`, `iso3`, `continentID`, `description`, `createdAt`, `updatedAt`) VALUES
(4, 'Кения', 'KEN', 3, 'Эталон яркой кислотности и ягодных профилей. Уникальная система аукционов и мытая обработка. Лоты SL28/SL34 с нотами черной смородины, томатов и цитрусов считаются одними из самых сложных и выразительных.', '2025-06-02 03:08:43', '2025-06-02 03:08:43'),
(5, 'Индонезия', 'IDN', 4, 'Родина знаменитой "суматра манделинг" с землистыми и пряными нотами. Острова Суматра, Ява и Сулавеси производят кофе с плотным телом. Отличается экспериментальными обработками (полусухая, "глинг-бай").', '2025-06-02 03:08:43', '2025-06-02 03:08:43'),
(6, 'Перу', 'PER', 1, 'Экологичный кофе из Андских высокогорий. Органические фермы дают сбалансированные лоты с нотами орехов, карамели и красных фруктов. Набирает популярность благодаря кооперативам мелких фермеров.', '2025-06-02 03:08:43', '2025-06-02 03:08:43'),
(7, 'Эфиопия', 'ETH', 3, 'Родина арабики. Уникальные "эфиопские наследственные" сорта с цветочно-фруктовыми профилями. Регионы Сидамо и Йиргачеффе - эталоны чайной легкости с нотами жасмина и голубики.', '2025-06-02 03:08:43', '2025-06-02 03:08:43'),
(8, 'Руанда', 'RWA', 3, '"Страна тысячи холмов" производит кофе с чистой ягодной кислотностью. После геноцида 1994 года кофе стал драйвером экономики. Лоты с нотами красных фруктов и карамели.', '2025-06-02 03:08:43', '2025-06-02 03:08:43'),
(9, 'Коста-Рика', 'CRI', 2, 'Пионер спешелти-движения в Центральной Америке. Запрет на робусту способствовал развитию качественной арабики. Тарразу и Вэлли Сентраль дают кофе с идеальным балансом сладости и кислотности.', '2025-06-02 03:08:43', '2025-06-02 03:08:43'),
(10, 'Китай', 'CHN', 4, 'Молодой, но перспективный производитель кофе, специализирующийся на высокогорных лотах из провинции Юньнань. Отличается необычными винно-ягодными профилями с нотами специй и тёмного шоколада.', '2025-06-02 03:08:43', '2025-06-02 03:08:43');
INSERT IGNORE INTO `processing_method` (`methodID`, `name`, `description`, `createdAt`, `updatedAt`) VALUES
(3, 'вет-халл', 'Полумытый метод: часть клейковины остаётся при сушке. Сочетает сладость натуральной и чистоту мытой обработки. Распространён в Суматре (Индонезия).', '2025-06-02 03:09:33', '2025-06-02 03:09:33'),
(4, 'мытый с термошоком', 'После ферментации зерна кратко нагревают, затем резко охлаждают. Усиливает сладость и создаёт необычные карамельные ноты. Фишка колумбийских фермеров.', '2025-06-02 03:09:33', '2025-06-02 03:09:33');
